# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    counts = {}
    for item in payload['entries']:
        counts[item['text']] = counts.get(item['text'], 0) + item['count']
    prefix = payload['prefix'].lower()
    matches = [text for text in counts if text.lower().startswith(prefix)]
    matches.sort(key=lambda text: (-counts[text], text.lower(), text))
    return [{'text': text, 'count': counts[text]} for text in matches[:payload['k']]]

